<?php elseif ($type==='slots'): $values=is_array($value)?$value:(is_string($value)?json_decode($value,true):[]); ?><fieldset class="php-fieldset"><legend><?= e($label) ?></legend><?php foreach (['breakfast','lunch','dinner','snacks'] as $meal): ?><label class="o-check"><input type="checkbox" name="slot_keys[]" value="<?= e($meal) ?>" <?= in_array($meal,$values?:[],true)?'checked':'' ?>><span class="o-switch-ui" aria-hidden="true"><i></i></span><span><?= e(ucfirst($meal)) ?></span></label><?php endforeach; ?><small>Select each meal this area serves.</small></fieldset>
<?php else: ?><label class="o-field"><span><?= e($label) ?></span>
