<?php if($key==='dishes'&&empty($_GET['date'])): $membership=$id?$store->db->rows("SELECT slot_id,weekday,available FROM catalog_menuschedule WHERE tenant_id=? AND item_id=? AND mode='weekday' ORDER BY slot_id,weekday",[$store->id(),$id]):[];$assignedSlot=$_POST['slot']??($membership[0]['slot_id']??'');$weekdays=$_POST['weekdays']??array_column(array_filter($membership,fn($m)=>(string)$m['slot_id']===(string)$assignedSlot&&$m['available']),'weekday'); ?><input type="hidden" name="schedule_present" value="1"><label class="o-field"><span>Meal time</span><select name="slot"><option value="">Not assigned / shop item</option><?php foreach($store->slots() as $mealSlot): ?><option value="<?= e($mealSlot['id']) ?>" <?= (string)$assignedSlot===(string)$mealSlot['id']?'selected':'' ?>><?= e($mealSlot['label']) ?></option><?php endforeach; ?></select><small>Choose the meal for a recurring weekly schedule. Saved dated menus keep their own selections.</small></label><fieldset class="php-fieldset o-field-wide"><legend>Weekdays</legend><?php foreach(['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'] as $day=>$label): ?><label style="display:inline-flex;gap:8px;margin:8px"><input name="weekdays[]" type="checkbox" value="<?= e($day) ?>" <?= in_array($day,array_map('intval',$weekdays),true)?'checked':'' ?>><?= e($label) ?></label><?php endforeach; ?></fieldset><?php endif; ?>
